"""Source-only artifact generation. No regression, model, or aerodynamic computation."""
import json,hashlib,csv
from pathlib import Path
from PIL import Image,ImageDraw
P=Path(__file__).parent
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
write=lambda n,x:(P/n).write_text(json.dumps(x,indent=2)+'\n')
cal=[]
for q,n,box,x0,x4,y0,y2,v2 in [('CN',24,[310,260,560,445],401.5,476.0,362.0,289.7,2),('Cm',25,[325,465,550,615],405.5,474.3,543.4,607.8,-2)]:
 cal.append({'id':f'd4013-{q.lower()}-m0p60','quantity':q,'source_page':n,'crop_box_pixels':box,'image':f'd4013-M0p60-{q}-crop.png','coordinate_system':'native 2px/PDFpoint crop, top-left(0,0), x right, y down; inspect4x images are not coordinate basis','x_anchors':[{'pixel':x0-box[0],'value':0},{'pixel':x4-box[0],'value':4}], 'y_anchors':[{'pixel':y0-box[1],'value':0},{'pixel':y2-box[1],'value':v2}], 'local_zero':'M0.60 local zero only; repeated lower Mach zeros excluded','pixel_pick_bound_xy':[3,3],'calibration_anchor_bound_px':2,'calibration_note':'Independent linear x/y transform on local panel. Small scan skew is not fitted; +/-2px bounded allowance includes local skew/anchor choice. Needs independent audit. Worst-case sum 5px used, no quadrature.'})
write('first-reader-calibrations.json',{'status':'first_reader_provisional','reader_id':'D1-subsonic-first-reader','calibrations':cal})
points=[]
picks={'CN':[(-2,363.8,373.0),(0,None,None),(2,438.5,346.7)],'Cm':[(-2,371.5,528.2),(0,None,None),(2,440.0,550.8)]}
for c in cal:
 q=c['quantity'];box=c['crop_box_pixels'];xa=c['x_anchors'];ya=c['y_anchors'];xs=(xa[1]['value']-xa[0]['value'])/(xa[1]['pixel']-xa[0]['pixel']);ys=(ya[1]['value']-ya[0]['value'])/(ya[1]['pixel']-ya[0]['pixel']); im=Image.open(P/c['image']).convert('RGB');draw=ImageDraw.Draw(im)
 for target,fx,fy in picks[q]:
  x=None if fx is None else fx-box[0];y=None if fy is None else fy-box[1];a=None if x is None else (x-xa[0]['pixel'])*xs;v=None if y is None else (y-ya[0]['pixel'])*ys
  if x is not None:draw.ellipse([x-5,y-5,x+5,y+5],outline='red',width=1);draw.text((x+6,y-10),str(target),fill='red')
  points.append({'point_id':f'{c["id"]}-target{target:+d}','series_id':c['id'],'source_sha256':'44dc62a4131cf31b88fab20566f2a4b934a16be17388e099192d25236f08324a','pdf_page_1based':c['source_page'],'figure':'7(b)' if q=='CN' else '7(c)','quantity':q,'conditions':{'mach':.60,'reynolds_definition':'unit Reynolds number 3e6/ft = reported 9.8e6/m; not body-length Reynolds','configuration':'short ARCAS L/d18.20, four fins on, square symbols','fin_cant_deg':0,'roll_definition':'0deg per source Fig7 legend; positive roll clockwise viewed upstream from aft; numeric simulator mapping unaudited','alpha_definition':'source corrected angle of model centerline, degrees; actual marker x retained','alpha_target_deg':target,'alpha_read_deg':a},'reference':{'axes':'source body axes; coefficient signs retained as plotted; exact simulator sign transform pending','area':'maximum body cross section S=pi*d^2/4, d reported5.72cm(2.25in); preserve rounding','moment_length':'body diameter d','moment_origin':'short-model station12.75d from nose in Fig1(a); text70%L with L18.20d, rounding retained','base_convention':'CN/Cm raw balance-derived; no axial/base correction applied'},'reading':{'image_sha256':sha(P/c['image']),'crop_box_pixels':box,'calibration_id':c['id'],'pixel_x':x,'pixel_y':y,'value':v,'reading_kind':'marker_center','marker':'square; neighboring roll symbols overlap','observation_status':'marker center manually read, provisional overlap identity' if x is not None else 'UNREADABLE: square center not distinguishable from overprinted symbols/axis ink; no measured center asserted','null_rule':'null means withheld, never zero or grid-intersection observation'},'uncertainty':{'digitization_bound':abs(5*ys),'alpha_digitization_bound_deg':abs(5*xs),'source_bound':.03 if q=='CN' else .05,'source_alpha_bound_deg':.1,'source_Mach_bound':.003,'source_roll_bound_deg':.5,'confidence_interpretation':'bounded reading/estimated calibration-repeatability limits, not probability intervals; source and extraction bounds separate','correlations':'shared source balance/calibration and scan/crop/axis anchors across points; reader agreement does not reduce common terms','unresolved_terms':['nearzero square-symbol overlap','local skew audit','first-pass marker identity audit','geometry/sign conventions independent review']},'review':{'reader_id':'D1-subsonic-first-reader','status':'first_reader_provisional' if x is not None else 'excluded','independent_reader_id':None,'disposition':'pending independent extraction; no fitting/scoring permitted' if x is not None else 'pending separate reader resolution; frozen target retained but no coefficient reading'}})
 # mark ambiguity ROI rather than a center
 zx=xa[0]['pixel'];zy=ya[0]['pixel'];draw.rectangle([zx-8,zy-8,zx+8,zy+8],outline='orange',width=1)
 im.save(P/c['image'].replace('-crop','-first-reader-picks'))
write('first-reader-points.json',points)
with (P/'first-reader-points.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['point_id','target_alpha_deg','actual_alpha_deg','coefficient','digitization_bound','source_bound','status'])
 for p in points:w.writerow([p['point_id'],p['conditions']['alpha_target_deg'],p['conditions']['alpha_read_deg'],p['reading']['value'],p['uncertainty']['digitization_bound'],p['uncertainty']['source_bound'],p['review']['status']])
